class Solution(object):
    def wiggleMaxLength(self, nums):
        """
        :type nums: List[int]
        :rtype: int
        """
        if len(nums) == 0:
            return 0
        dp1 = [1] * len(nums)
        dp2 = [1] * len(nums)
        for i in range(1, len(nums)):
            for j in range(i):
                if nums[i] > nums[j]:
                    dp2[i] = max(dp2[i], dp1[j] + 1)
                elif nums[i] < nums[j]:
                    dp1[i] = max(dp1[i], dp2[j] + 1)
        return max(max(dp1), max(dp2))
